import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        int nextInt() throws IOException {
            while (ptr < len || (len = in.read(buffer)) != -1) {
                if (ptr >= len) {
                    ptr = 0;
                    continue;
                }
                if (buffer[ptr] > ' ') break;
                ptr++;
            }
            int value = 0;
            while (ptr < len || (len = in.read(buffer)) != -1) {
                if (ptr >= len) {
                    ptr = 0;
                    continue;
                }
                if (buffer[ptr] <= ' ') break;
                value = value * 10 + buffer[ptr++] - '0';
            }
            ptr++;
            return value;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();

        int[] head = new int[n];
        Arrays.fill(head, -1);
        int[] to = new int[2 * (n - 1)];
        int[] next = new int[2 * (n - 1)];
        int edgeIndex = 0;

        for (int i = 0; i < n - 1; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;

            to[edgeIndex] = b;
            next[edgeIndex] = head[a];
            head[a] = edgeIndex++;

            to[edgeIndex] = a;
            next[edgeIndex] = head[b];
            head[b] = edgeIndex++;
        }

        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        int[] order = new int[n];
        int count = 1;
        order[0] = 0;
        parent[0] = 0;

        for (int i = 0; i < count; i++) {
            int u = order[i];
            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (parent[v] == -1) {
                    parent[v] = u;
                    order[count++] = v;
                }
            }
        }

        int[] subtreeSize = new int[n];
        Arrays.fill(subtreeSize, 1);
        int answer = n;

        for (int i = n - 1; i > 0; i--) {
            int u = order[i];
            answer = Math.min(answer, Math.abs(n - 2 * subtreeSize[u]));
            subtreeSize[parent[u]] += subtreeSize[u];
        }

        System.out.println(answer);
    }
}
